  @protected
  void sse_encode_web_view_execution_completion_dto(
    WebViewExecutionCompletionDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case WebViewExecutionCompletionDto_Success(outputs: final outputs):
        sse_encode_i_32(0, serializer);
        sse_encode_list_record_string_string(outputs, serializer);
      case WebViewExecutionCompletionDto_Failed(message: final message):
        sse_encode_i_32(1, serializer);
        sse_encode_String(message, serializer);
      case WebViewExecutionCompletionDto_Cancelled():
        sse_encode_i_32(2, serializer);
      case WebViewExecutionCompletionDto_WaitTimeout(
        role: final role,
        selector: final selector,
        forSelector: final forSelector,
        condition: final condition,
        timeoutMs: final timeoutMs,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_binding_role_dto(role, serializer);
        sse_encode_String(selector, serializer);
        sse_encode_String(forSelector, serializer);
        sse_encode_binding_wait_condition_dto(condition, serializer);
        sse_encode_u_64(timeoutMs, serializer);
    }
  }

